enum PartnerLoginStatus {
  signedIn('signed_in'),
  codeRequired('code_required'),
  unknown('unknown');

  const PartnerLoginStatus(this.value);

  /// The wire value.
  final String value;

  /// Unknown values never crash a client: they read as [unknown] (api-conventions section 2).
  static PartnerLoginStatus fromJson(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return PartnerLoginStatus.unknown;
  }

  String toJson() => value;
}

